package sfz.stream.l03.demo

/**
 * Lesson stream-03, Try it 1: one account as a table row, and the same account as a log of events.
 * The row holds the answer; the log also holds the reasons, and every earlier answer.
 */

sealed interface Event { val text: String }
data class Opened(val owner: String) : Event { override val text = "AccountOpened   owner=$owner" }
data class Deposited(val cents: Long, val ref: String) : Event { override val text = "MoneyDeposited  +${eur(cents)}  ref=$ref" }
data class Withdrawn(val cents: Long, val ref: String) : Event { override val text = "MoneyWithdrawn  -${eur(cents)}  ref=$ref" }

fun eur(cents: Long) = "%d.%02d".format(cents / 100, cents % 100)

/** The state is a fold: start from nothing and apply each event in order. */
fun balance(events: List<Event>): Long = events.fold(0L) { b, e ->
    when (e) {
        is Opened -> 0
        is Deposited -> b + e.cents
        is Withdrawn -> b - e.cents
    }
}

fun main() {
    val log = listOf(
        Opened("Mira Okafor"),
        Deposited(10_000, "salary-0301"),
        Withdrawn(3_000, "card pay-981"),
        Withdrawn(4_500, "card pay-982"),
        Deposited(4_500, "refund of pay-982"),
        Withdrawn(5_000, "transfer tx-77"),
    )
    println("the table:  accounts(id = 'acct-17', balance = ${eur(balance(log))})")
    println()
    println("the log:    stream account-acct-17")
    log.forEachIndexed { i, e ->
        println("  v${i + 1}  %-46s balance %7s".format(e.text, eur(balance(log.take(i + 1)))))
    }
    println()
    // a question the table can't answer: what was the balance before the transfer?
    println("balance as of v5 (before tx-77): ${eur(balance(log.take(5)))}")
    println("events that mention pay-982:     ${log.withIndex().filter { "pay-982" in it.value.text }.map { "v${it.index + 1}" }}")
}

package sfz.stream.l03.demo

/**
 * Lesson stream-03, Try it 2: two command handlers withdraw 80.00 from an account that holds
 * 100.00, each after checking the balance it loaded. First with a store that appends blindly, then
 * with a store that checks the stream version the handler saw.
 */

class VersionConflict(msg: String) : RuntimeException(msg)

class Stream(private val checkVersion: Boolean) {
    val events = mutableListOf<Long>()                  // signed amounts in cents, oldest first

    fun load(): Pair<Long, Int> = events.sum() to events.size   // (balance, version)

    fun append(expectedVersion: Int, amount: Long) {
        if (checkVersion && events.size != expectedVersion) {
            throw VersionConflict("expected version $expectedVersion, stream is at ${events.size}")
        }
        events += amount
    }
}

/** The aggregate's rule: no withdrawal larger than the balance it knows about. */
fun withdraw(stream: Stream, name: String, cents: Long, loaded: Pair<Long, Int>) {
    val (balance, version) = loaded
    if (cents > balance) { println("  $name: rejected, balance is ${eur(balance)}"); return }
    try {
        stream.append(version, -cents)
        println("  $name: saw v$version, balance ${eur(balance)}: appended MoneyWithdrawn -${eur(cents)} as event ${stream.events.size}")
    } catch (e: VersionConflict) {
        println("  $name: conflict, ${e.message}")
        val fresh = stream.load()
        print("  $name: reloads v${fresh.second}, balance ${eur(fresh.first)}, and decides again -> ")
        if (cents > fresh.first) println("rejected: insufficient funds") else { stream.append(fresh.second, -cents); println("appended") }
    }
}

fun main() {
    for (check in listOf(false, true)) {
        val stream = Stream(checkVersion = check)
        stream.append(0, 0)                              // v1 AccountOpened (amount 0)
        stream.append(1, 10_000)                         // v2 MoneyDeposited 100.00
        println(if (check) "append with expected version:" else "append without a version check:")
        val a = stream.load()                            // both handlers load before either appends
        val b = stream.load()
        withdraw(stream, "handler A", 8_000, a)
        withdraw(stream, "handler B", 8_000, b)
        println("  final: ${stream.events.size} events, balance ${eur(stream.events.sum())}")
        println()
    }
}

package sfz.stream.l03.demo

import kotlin.random.Random

/**
 * Lesson stream-03, Try it 3: what replay costs. One busy account with 200,000 events is loaded
 * from scratch and from a snapshot; then a brand-new read model is built over a log of 2,000,000
 * events. Events are stored as text and parsed on every read, as a real store would deserialize them.
 */

/** "D|acct-17|4000" or "W|acct-17|2500": a deposit or withdrawal, in cents. */
fun parse(line: String): Triple<Char, String, Long> {
    val a = line.indexOf('|')
    val b = line.indexOf('|', a + 1)
    return Triple(line[0], line.substring(a + 1, b), line.substring(b + 1).toLong())
}

fun applyTo(balance: Long, line: String): Long {
    val (type, _, cents) = parse(line)
    return if (type == 'D') balance + cents else balance - cents
}

/** Best of five runs, in milliseconds: the first runs also pay for the JIT compiler. */
fun timeMs(block: () -> Any): Double = (1..5).minOf { val t = System.nanoTime(); block(); (System.nanoTime() - t) / 1e6 }

fun main() {
    val random = Random(7)
    // one merchant settlement account with a long history
    val busy = List(200_000) { i -> if (i % 3 == 0) "W|acct-merchant-7|${random.nextLong(100, 900)}" else "D|acct-merchant-7|${random.nextLong(100, 900)}" }

    val full = timeMs { busy.fold(0L, ::applyTo) }
    val snapshotAt = busy.size - 100                                   // a snapshot every 1,000 events, the last one 100 events ago
    val snapshot = busy.take(snapshotAt).fold(0L, ::applyTo)            // stored once, read many times
    val fromSnapshot = timeMs { busy.drop(snapshotAt).fold(snapshot, ::applyTo) }
    check(busy.drop(snapshotAt).fold(snapshot, ::applyTo) == busy.fold(0L, ::applyTo))
    println("load acct-merchant-7 (200,000 events) from scratch:       %8.3f ms".format(full))
    println("load it from a snapshot at v%d + 100 events:          %8.3f ms".format(snapshotAt, fromSnapshot))

    // the whole store: 2,000,000 events over 50,000 accounts
    val log = List(2_000_000) { i -> "${if (i % 4 == 0) 'W' else 'D'}|acct-${random.nextInt(50_000)}|${random.nextLong(100, 90_000)}" }
    var large = 0
    val rebuild = timeMs {
        large = 0
        val balances = HashMap<String, Long>()
        for (line in log) {
            val (type, account, cents) = parse(line)
            balances.merge(account, if (type == 'D') cents else -cents, Long::plus)
            if (type == 'W' && cents >= 50_000) large++                      // the new "large withdrawals" view
        }
        balances
    }
    println("rebuild two read models from 2,000,000 events:            %8.1f ms  (%,d large withdrawals found)".format(rebuild, large))
}

package sfz.stream.l03.demo

import java.math.BigDecimal

/**
 * Lesson stream-03, Try it 4: three ways to read an event that last year's code wrote. The stored
 * events are maps, as JSON objects would be; the current reader wants MoneyWithdrawn version 2,
 * {accountId, amountMinor, currency}. Version 1 was {accountId, amount} with euros as text.
 */

data class Stored(val position: Long, val type: String, val schemaVersion: Int, val data: Map<String, String>)

val storedLog = listOf(
    Stored(1, "MoneyWithdrawn", 1, mapOf("accountId" to "acct-17", "amount" to "80.00")),        // last year
    Stored(2, "MoneyWithdrawn", 2, mapOf("accountId" to "acct-17", "amountMinor" to "1250", "currency" to "EUR")),
)

/** Today's reader: it knows only version 2. */
fun strictRead(e: Stored): Long = e.data["amountMinor"]?.toLong() ?: error("position ${e.position}: no field amountMinor")

/** A weak schema: read what you can, fall back on what you know about older shapes. */
fun tolerantRead(e: Stored): Long =
    e.data["amountMinor"]?.toLong() ?: BigDecimal(e.data.getValue("amount")).movePointRight(2).longValueExact()

/** An upcaster: turn version 1 into version 2 as it is read, so the rest of the code sees one shape. */
fun upcast(e: Stored): Stored =
    if (e.type == "MoneyWithdrawn" && e.schemaVersion == 1) {
        e.copy(
            schemaVersion = 2,
            data = mapOf(
                "accountId" to e.data.getValue("accountId"),
                "amountMinor" to BigDecimal(e.data.getValue("amount")).movePointRight(2).longValueExact().toString(),
                "currency" to "EUR",
            ),
        )
    } else e

fun main() {
    for (e in storedLog) {
        val strict = runCatching { strictRead(e) }.fold({ "$it" }, { "fails: ${it.message}" })
        println("position ${e.position}, schema ${e.schemaVersion}: strict reader $strict")
    }
    println("tolerant reader:        ${storedLog.map(::tolerantRead)}")
    println("upcast, then strict:    ${storedLog.map(::upcast).map(::strictRead)}")
    println("upcast event 1:         ${upcast(storedLog[0])}")
    println("stored event 1 is still ${storedLog[0]}")
    // copy and replace: write a new stream with every event upcast, check it, then point readers at it
    val copied = storedLog.map(::upcast)
    println("copy and replace:       new stream of ${copied.size} events, all schema ${copied.map { it.schemaVersion }.distinct()}")
}

