fun evolve(s: AccountState, e: AccountEvent) = when (e) {
    is AccountOpened -> s.copy(opened = true, owner = e.owner)
    is MoneyDeposited -> s.copy(balanceMinor = s.balanceMinor + e.amountMinor)
    is MoneyWithdrawn -> s.copy(balanceMinor = s.balanceMinor - e.amountMinor)
}

fun decide(s: AccountState, c: AccountCommand): List<AccountEvent> = when (c) {
    is OpenAccount -> if (s.opened) throw Rejected("already open") else listOf(AccountOpened(c.accountId, c.owner))
    is Deposit -> { check(s, c.amountMinor); listOf(MoneyDeposited(c.accountId, c.amountMinor)) }
    is Withdraw -> {
        check(s, c.amountMinor)
        if (c.amountMinor > s.balanceMinor) throw Rejected("insufficient funds")
        listOf(MoneyWithdrawn(c.accountId, c.amountMinor, "EUR"))
    }
}

// the handler
val loaded = load(id)                                     // fold + the version it saw
val events = decide(loaded.state, cmd)
store.append("account-$id", loaded.version, events.map(Codec::encode))   // refused if someone appended first

